// Writes lib/cover-icon-shapes.ts: every lucide icon, as the shapes
// that make it up.
//
// Why a generated file rather than reaching for the icon at request
// time. The obvious version imports
// `lucide-react/dist/esm/icons/${name}.mjs` when a cover is drawn, and
// it works perfectly on a laptop, where node_modules is sitting there.
// Next's file tracing cannot follow an import built from a variable, so
// nothing is traced, nothing is deployed, and on Vercel every cover
// comes out a plain gradient with no mark on it. Silently, because the
// failure is a caught import.
//
// So the shapes are read once, here, and committed. The route imports
// the JSON like any other file and the tracer can see it.
//
// Read by importing each icon module, not by parsing it: every one
// exports its own __iconData beside the component. A first attempt
// regex-matched the source and quietly dropped a shape wherever the
// attributes ran across lines, which is how Beer lost its foam.
//
// Run after upgrading lucide-react:  node scripts/build-cover-icons.mjs
import { readdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";

// lucide's own search words, so "cocktail" finds Martini and "barber"
// finds Scissors. They are not in lucide-react — it ships components,
// not metadata — so they come from lucide-static, which is the same
// project publishing the same icons. Fetched rather than depended on:
// that package is 57MB unpacked for one file of a few hundred
// kilobytes.
//
// Pinned to the version of lucide-react in package.json, so the words
// describe the icons we actually draw. If the fetch fails the file is
// still written, just without tags, and search falls back to names.
const TAGS = (version) => `https://unpkg.com/lucide-static@${version}/tags.json`;

const ICONS = "node_modules/lucide-react/dist/esm/icons";
const OUT = "lib/cover-icon-shapes.ts";

// "utensils-crossed" is the file; "UtensilsCrossed" is the name that
// travels, and the one lucide-react exports.
const pascal = (file) =>
    file.replace(/(^|-)([a-z0-9])/g, (_, __, c) => c.toUpperCase());

const { default: pkg } = await import("../package.json", { with: { type: "json" } });
const version = pkg.dependencies["lucide-react"].replace(/^[^0-9]*/, "");

let tags = {};

try {
    const response = await fetch(TAGS(version));

    if (!response.ok) throw new Error(String(response.status));

    tags = await response.json();
    console.log(`tags for ${Object.keys(tags).length} icons from lucide-static@${version}`);
} catch (error) {
    console.warn(`no tags (${error.message}) — search will match names only`);
}

const shapes = {};
const words = {};
const dropped = [];

for (const file of readdirSync(ICONS).sort()) {
    if (!file.endsWith(".mjs")) continue;

    const name = pascal(file.replace(/\.mjs$/, ""));

    try {
        const { __iconData } = await import(`../${join(ICONS, file)}`);
        const node = __iconData?.node;

        if (!Array.isArray(node) || node.length === 0) {
            dropped.push(name);
            continue;
        }

        // The key is React's, and nothing here renders through React.
        shapes[name] = node.map(([tag, attributes]) => {
            const { key, ...rest } = attributes ?? {};

            return [tag, rest];
        });

        // Keyed by the same name the shapes are, and only where there
        // are any — an empty array per icon would be a third of the
        // file saying nothing.
        const found = tags[file.replace(/\.mjs$/, "")];

        if (found?.length) words[name] = found;
    } catch {
        dropped.push(name);
    }
}

// A module rather than a .json, so neither Node's test runner nor the
// bundler needs an import attribute, and the type is stated once here
// instead of cast at every use.
writeFileSync(
    OUT,
    [
        "// Generated by scripts/build-cover-icons.mjs. Do not edit.",
        "//",
        "// Every lucide icon, as the shapes that draw it. Regenerate after",
        "// upgrading lucide-react: node scripts/build-cover-icons.mjs",
        "",
        "export type IconShapes = [string, Record<string, string>][];",
        "",
        `const shapes: Record<string, IconShapes> = ${JSON.stringify(shapes)};`,
        "",
        "// lucide's own search words: Martini is tagged \"cocktail\", which is",
        "// the word somebody actually types.",
        `export const iconTags: Record<string, string[]> = ${JSON.stringify(words)};`,
        "",
        "export default shapes;",
        "",
    ].join("\n"),
);

console.log(`${Object.keys(shapes).length} icons written to ${OUT}, ${Object.keys(words).length} with search words`);
if (dropped.length) console.log(`${dropped.length} skipped: ${dropped.slice(0, 5).join(", ")}…`);
